"use client";
import type { MealDrop } from "@mealhrs/domain";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Status } from "@/components/ui/status";
import { isCutoffPassed } from "@/features/meal-drops/effective-availability";
import styles from "./vendor-operations.module.css";
export function VendorDropsView({ mealDrops, now }: Readonly<{ mealDrops: readonly MealDrop[]; now: string }>) { const [closed, setClosed] = useState<Set<string>>(new Set()); const [feedback, setFeedback] = useState(""); return <div><header className={styles.head}><div><p className={styles.eyebrow}>Pre-orders</p><h1>Meal Drops</h1><p>Manage scheduled batches separately from immediate kitchen availability.</p></div><Button size="sm" onClick={() => setFeedback("Meal Drop creation is a frontend preview; no scheduled drop has been saved.")}>Create Meal Drop</Button></header>{feedback ? <p className={styles.feedback} role="status">{feedback}</p> : null}<section className={styles.list}>{mealDrops.map((drop) => { const cutoffPassed = isCutoffPassed(drop.cutoffAt, now); const statusLabel = cutoffPassed || drop.status === "cutoff_passed" ? "Cutoff passed" : drop.remainingCapacity <= 0 || drop.status === "sold_out" ? "Sold out" : drop.status === "cancelled" ? "Cancelled" : closed.has(drop.id) ? "Closed" : "Open for pre-order"; const isClosed = statusLabel !== "Open for pre-order"; const sold = drop.capacity - drop.remainingCapacity; return <article className={`card ${styles.drop}`} key={drop.id}><div><div className="cluster"><Status tone={isClosed ? "neutral" : "success"}>{statusLabel}</Status><span className={styles.fact}>{drop.fulfillmentDate} · {drop.fulfillmentWindow}</span></div><h2>{drop.name}</h2><p>{drop.description}</p><div className={styles.dropProgress} aria-label={`${sold} of ${drop.capacity} places reserved`}><span style={{ width: `${Math.round((sold / drop.capacity) * 100)}%` }}/></div><div className={styles.facts}><span className={styles.fact}>{sold} reserved · {drop.remainingCapacity} remaining</span></div></div><div className={styles.actionGroup}><Button size="sm" variant="secondary" onClick={() => setFeedback(`${drop.name} is ready for editing in a future persistent workflow.`)}>Edit</Button><Button size="sm" variant={isClosed ? "secondary" : "danger"} disabled={isClosed} onClick={() => { setClosed((current) => new Set(current).add(drop.id)); setFeedback(`${drop.name} is closed in this frontend preview.`); }}>{isClosed ? statusLabel : "Close pre-orders"}</Button></div></article>; })}</section></div>; }
